-- Setup script for Observability SDK database tables
-- Run this script on your target database before using the SDK

-- Ensure we're using the public schema
SET search_path TO public;

-- Create sessions table
CREATE TABLE IF NOT EXISTS public."sessions" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"start_time" timestamp DEFAULT now() NOT NULL,
	"end_time" timestamp,
	"total_tools" integer DEFAULT 0 NOT NULL,
	"successful_tools" integer DEFAULT 0 NOT NULL,
	"failed_tools" integer DEFAULT 0 NOT NULL,
	"outcome" text,
	"description" text,
	"organization_id" text,
	"user_id" text
);

-- Create tool_calls table
CREATE TABLE IF NOT EXISTS public."tool_calls" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"session_id" uuid NOT NULL,
	"tool_name" text NOT NULL,
	"status" text NOT NULL,
	"created_at" timestamp DEFAULT now() NOT NULL,
	"started_at" timestamp,
	"completed_at" timestamp,
	"duration" integer,
	"error_message" text,
	"organization_id" text,
	"user_id" text
);

-- Create pre_hook_logs table
CREATE TABLE IF NOT EXISTS public."pre_hook_logs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tool_call_id" uuid NOT NULL,
	"tool_name" text NOT NULL,
	"tool_input" text NOT NULL,
	"session_id" uuid NOT NULL,
	"hook_event_name" text NOT NULL,
	"transcript_path" text,
	"cwd" text,
	"prompt" text,
	"start_timestamp" timestamp NOT NULL,
	"timestamp" timestamp DEFAULT now() NOT NULL
);

-- Create post_hook_logs table
CREATE TABLE IF NOT EXISTS public."post_hook_logs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"tool_call_id" uuid NOT NULL,
	"tool_name" text NOT NULL,
	"tool_response" text NOT NULL,
	"session_id" uuid NOT NULL,
	"hook_event_name" text NOT NULL,
	"transcript_path" text,
	"cwd" text,
	"success" boolean NOT NULL,
	"error_message" text,
	"duration_ms" integer,
	"end_timestamp" timestamp NOT NULL,
	"output_tokens" integer,
	"total_tokens" integer,
	"estimated_cost" real,
	"timestamp" timestamp DEFAULT now() NOT NULL
);

-- Create indexes for better performance
CREATE INDEX IF NOT EXISTS idx_pre_hook_logs_session_id ON pre_hook_logs(session_id);
CREATE INDEX IF NOT EXISTS idx_post_hook_logs_session_id ON post_hook_logs(session_id);
CREATE INDEX IF NOT EXISTS idx_pre_hook_logs_tool_call_id ON pre_hook_logs(tool_call_id);
CREATE INDEX IF NOT EXISTS idx_post_hook_logs_tool_call_id ON post_hook_logs(tool_call_id);

-- Add foreign key constraints (optional, can be skipped if causing issues)
DO $$ BEGIN
 ALTER TABLE "tool_calls" ADD CONSTRAINT "tool_calls_session_id_sessions_id_fk"
 FOREIGN KEY ("session_id") REFERENCES "public"."sessions"("id") ON DELETE no action ON UPDATE no action;
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
 ALTER TABLE "pre_hook_logs" ADD CONSTRAINT "pre_hook_logs_tool_call_id_tool_calls_id_fk"
 FOREIGN KEY ("tool_call_id") REFERENCES "public"."tool_calls"("id") ON DELETE no action ON UPDATE no action;
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;

DO $$ BEGIN
 ALTER TABLE "post_hook_logs" ADD CONSTRAINT "post_hook_logs_tool_call_id_tool_calls_id_fk"
 FOREIGN KEY ("tool_call_id") REFERENCES "public"."tool_calls"("id") ON DELETE no action ON UPDATE no action;
EXCEPTION
 WHEN duplicate_object THEN null;
END $$;

-- User Prompt logs table
CREATE TABLE IF NOT EXISTS public.user_prompt_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id UUID NOT NULL,
  hook_event_name TEXT NOT NULL,
  transcript_path TEXT,
  cwd TEXT,
  prompt TEXT NOT NULL,
  character_count INTEGER NOT NULL,
  word_count INTEGER NOT NULL,
  input_tokens INTEGER,
  estimated_cost REAL,
  timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
  organization_id TEXT,
  user_id TEXT
);

-- Session Start logs table
CREATE TABLE IF NOT EXISTS public.session_start_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id UUID NOT NULL,
  hook_event_name TEXT NOT NULL,
  transcript_path TEXT,
  source TEXT,
  "user" TEXT,
  hostname TEXT,
  working_directory TEXT,
  platform TEXT,
  shell TEXT,
  timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
  organization_id TEXT,
  user_id TEXT
);

-- Session End logs table
CREATE TABLE IF NOT EXISTS public.session_end_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id UUID NOT NULL,
  hook_event_name TEXT NOT NULL,
  transcript_path TEXT,
  cwd TEXT,
  reason TEXT,
  session_stats TEXT,
  timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
  organization_id TEXT,
  user_id TEXT
);

-- Subagent Stop logs table
CREATE TABLE IF NOT EXISTS public.subagent_stop_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id UUID NOT NULL,
  hook_event_name TEXT NOT NULL,
  transcript_path TEXT,
  stop_hook_active BOOLEAN NOT NULL,
  completion_type TEXT,
  timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
  organization_id TEXT,
  user_id TEXT
);

-- Stop logs table (for main session stop events)
CREATE TABLE IF NOT EXISTS public.stop_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id UUID NOT NULL,
  hook_event_name TEXT NOT NULL,
  transcript_path TEXT,
  cwd TEXT,
  stop_hook_active BOOLEAN NOT NULL,
  permission_mode TEXT,
  timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
  organization_id TEXT,
  user_id TEXT
);

-- Notification logs table
CREATE TABLE IF NOT EXISTS public.notification_logs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  session_id UUID NOT NULL,
  hook_event_name TEXT NOT NULL,
  transcript_path TEXT,
  cwd TEXT,
  message TEXT NOT NULL,
  timestamp TIMESTAMP NOT NULL DEFAULT NOW(),
  organization_id TEXT,
  user_id TEXT
);